code.cpp:
class Solution {
public:
    int calculate(string s) {
        long long result = 0;
        long long last = 0;
        long long num = 0;
        char op = '+';
        int n = s.size();
        for (int i = 0; i < n; i++) {
            char c = s[i];
            if (c >= '0' && c <= '9') {
                num = num * 10 + (c - '0');
            }
            if (((c < '0' || c > '9') && c != ' ') || i == n - 1) {
                if (op == '+') {
                    result += last;
                    last = num;
                } else if (op == '-') {
                    result += last;
                    last = -num;
                } else if (op == '*') {
                    last = last * num;
                } else if (op == '/') {
                    last = last / num;
                }
                op = c;
                num = 0;
            }
        }
        result += last;
        return (int)result;
    }
};
